package com.esn.smp.gameplay;
import org.bukkit.ChatColor;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;
public final class ESNItemsCommand implements CommandExecutor{
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player p))return true;if(!p.hasPermission("esnsmp.items")){p.sendMessage(ChatColor.RED+"No permission.");return true;}if(a.length==0){p.sendMessage(ChatColor.GOLD+"/esnitems <key|titanblade|titanhelmet|titanchest|titanlegs|titanboots|voidblade|voidbreaker|voidcrown|voidchest|voidlegs|voidboots|titancleaver|infernal|celestialbow|titandrill|lifecore>");return true;}ItemStack i=switch(a[0].toLowerCase()){case"key"->new SMPGameplay(null).key();case"titanblade"->CustomItems.titanBlade();case"titanhelmet"->CustomItems.titanHelmet();case"titanchest"->CustomItems.titanChestplate();case"titanlegs"->CustomItems.titanLeggings();case"titanboots"->CustomItems.titanBoots();case"voidblade"->CustomItems.voidBlade();case"voidbreaker"->CustomItems.voidPick();case"voidcrown"->CustomItems.voidHelmet();case"voidchest"->CustomItems.voidChestplate();case"voidlegs"->CustomItems.voidLeggings();case"voidboots"->CustomItems.voidBoots();case"titancleaver"->CustomItems.titanAxe();case"infernal"->CustomItems.infernalBlade();case"celestialbow"->CustomItems.celestialBow();case"titandrill"->CustomItems.minerDrill();case"lifecore"->CustomItems.lifeApple();default->null;};if(i==null){p.sendMessage(ChatColor.RED+"Unknown ESN item.");return true;}p.getInventory().addItem(i);p.sendMessage(ChatColor.GREEN+"Added "+i.getItemMeta().getDisplayName());return true;}
}